import { useState } from "react";
import commonStyles from "../InputStyles.module.scss";
import { AiOutlineEye, AiOutlineEyeInvisible } from "react-icons/ai";

interface TextInputProps {
  label?: string;
  customClassName?: string;
  errorMessage?: string;
  placeholder?: string;
  type?: "text" | "password" | "email" | "number" | "tel";
  value?: string | number;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
}
const TextInput: React.FC<TextInputProps> = ({
  label,
  customClassName,
  errorMessage,
  placeholder,
  type = "password",
  ...props
}) => {
  const [showPassword, setShowPassword] = useState(false);
  const isPasswordType = type === "password";

  return (
    <div className={commonStyles["inputWrapper"]}>
      {label && <label className={commonStyles["labelInput"]}>{label}</label>}

      <div className={commonStyles.inputContainer}>
        <input
          className={commonStyles["textInput"]}
          type={type}
          placeholder={placeholder}
          {...props}
        />
        {isPasswordType && (
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className={commonStyles.togglePassword}
            aria-label={showPassword ? "Hide password" : "Show password"}
            tabIndex={-1}
          >
            {showPassword ? (
              <AiOutlineEyeInvisible size={20} />
            ) : (
              <AiOutlineEye size={20} />
            )}
          </button>
        )}
      </div>

      {errorMessage && (
        <span className={commonStyles["errorMessage"]}>{errorMessage}</span>
      )}
    </div>
  );
};

export default TextInput;
